/**
 * posts.js — loads blog content from /content/posts.
 *   index.json   -> list of post metadata (generated by `npm run posts`)
 *   <slug>.md    -> the markdown body, with a front-matter header
 */
import { parseFrontMatter } from "./frontmatter.js";

const POSTS_DIR = "content/posts";

/** Fetch the list of posts, newest first. */
export async function fetchPostIndex() {
  const res = await fetch(`${POSTS_DIR}/index.json`);
  if (!res.ok) throw new Error("Could not load the post index.");
  const { posts } = await res.json();
  return posts;
}

/** Fetch one post by slug. Returns null if it doesn't exist. */
export async function fetchPost(slug) {
  // Slugs are restricted so they can't be used to reach other files.
  if (!/^[a-z0-9-]+$/.test(slug)) return null;

  const res = await fetch(`${POSTS_DIR}/${slug}.md`);
  if (!res.ok) return null;

  const { meta, body } = parseFrontMatter(await res.text());
  return { slug, ...meta, body };
}
